class Solution {
public:
    string gameResult(ListNode* head) {
        int even = 0, odd = 0;
        while (head && head->next) {
            if (head->val > head->next->val) ++even;
            else ++odd;
            head = head->next->next;
        }
        return even > odd ? "Even" : odd > even ? "Odd" : "Tie";
    }
};
